html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{% if letter_head and not no_letterhead %}
		<div class="letter-head" style="margin-bottom: 0px !important;">{{ letter_head }}</div>
	{% endif %}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break invoice-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>

	<style>
		.invoice-wrapper {
			font-family: "Arial", sans-serif;
			color: #000;
			font-size: 12px;
		}
		.print-format-body {
			padding: 0px !important;
			margin-top: 5px !important;
		}
		.text-center { text-align: center; }
		.text-left { text-align: left; }
		.text-right { text-align: right; }
		.text-bold { font-weight: bold; }

		.info-table {
			width: 100%;
			margin-bottom: 8px; 
			border-collapse: collapse;
		}
		.info-table td {
			vertical-align: top;
			line-height: 1.2; 
			padding: 0px !important;
		}

		.right-info-table {
			width: 100%;
			border-collapse: collapse;
		}
		.right-info-table td {
			padding: 0px !important;
			line-height: 1.2;
		}

		table.items-table {
			width: 100%;
			border-collapse: collapse;
			margin-bottom: 8px;
			border: 1px solid #000;
		}

		table.items-table th, 
		table.items-table td {
			border: 1px solid #000;
			padding: 1px 4px !important; 
			height: 6mm !important;
			line-height: 1.1 !important;
			vertical-align: middle !important;
		}
		table.items-table th {
			background-color: #f0f0f0;
			text-align: center;
			font-weight: bold;
		}

		.totals-row td, .amount-words-row td {
			border: 1px solid #000;
			padding: 1px 4px !important; 
			height: 6mm !important;
			line-height: 1.1 !important;
			vertical-align: middle !important;
		}

		.signature-section {
			width: 100%;
			margin-top: 15px; 
			margin-bottom: 0px !important; /* Reduced to avoid extra blank pages */
			border-collapse: collapse;
			page-break-inside: avoid; /* Prevents awkward page splits */
		}
		.signature-section td {
			width: 33%;
			vertical-align: bottom;
			text-align: center;
		}

		.terms-section {
			font-size: 11px;
			line-height: 1.4;
			margin-top: 15px;
			page-break-inside: avoid;
		}

        .letter-head-footer {
            margin-top: 5px;
        }
	</style>

	<div class="print-format-body">

		<table class="info-table">
			<tr>
				<td style="width: 55%; padding-right: 10px !important;">
					<strong>To,</strong><br>
					<strong>{{ doc.customer_name or doc.party_name }}</strong><br>
					{% if doc.customer_address %}
						{% set customer_address = frappe.db.get_value("Address", doc.customer_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
						{% if customer_address.address_line1 %}{{ customer_address.address_line1 }}<br>{% endif %}
						{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}
						{% if customer_address.city or customer_address.country %}{{ customer_address.city or "" }}{% if customer_address.city and customer_address.country %}, {% endif %}{{ customer_address.country or "" }}<br>{% endif %}
					{% endif %}

                    {% if doc.tax_id %}<strong>TRN:</strong> {{ doc.tax_id }}<br>{% endif %}
					{% if doc.project %}<strong>Project :</strong> {{ doc.project }}<br>{% endif %}
					{% if doc.contact_display %}<strong>Attn:</strong> {{ doc.contact_display }}{% endif %}
				</td>
				<td style="width: 45%;">
					<table class="right-info-table">
						<tr><td style="width: 40%;">Quote No</td><td>: <strong>{{ doc.name }}</strong></td></tr>
						<tr><td>Date</td><td>: {{ frappe.utils.format_date(doc.transaction_date) }}</td></tr>
						{% if doc.valid_till %}<tr><td>Valid Till</td><td>: {{ frappe.utils.format_date(doc.valid_till) }}</td></tr>{% endif %}
						<tr><td>Payment Terms</td><td>: {{ doc.payment_terms_template or doc.cen_payment_terms or "" }}</td></tr>
					</table>
				</td>
			</tr>
		</table>

		<!-- Items Table -->
		<table class="items-table">
			<thead>
				<tr>
					<th style="width: 5%;">Sl No.</th>
					<th style="width: 55%; text-align: left;">DESCRIPTION</th>
					<th style="width: 7%;">QTY</th>
					<th style="width: 8%;">Unit</th>
					<th style="width: 12%;">RATE</th>
					<th style="width: 13%;">AMOUNT</th>
				</tr>
			</thead>
			<tbody>
				{% for item in doc.items %}
				<tr>
					<td class="text-center">{{ loop.index }}</td>
					<td>{{ item.item_name }}{% if item.description and item.description != item.item_name %}<br><span style="font-size: 10px;">{{ item.description }}</span>{% endif %}</td>
					<td class="text-center">{{ item.get_formatted("qty", 0) }}</td>
					<td class="text-center">{{ item.uom }}</td>
					<td class="text-right">{{ item.get_formatted("rate", doc) }}</td>
					<td class="text-right">{{ item.get_formatted("amount", doc) }}</td>
				</tr>
				{% endfor %}

				<tr class="totals-row">
					<td colspan="5" class="text-right">TOTAL</td>
					<td class="text-right text-bold">{{ doc.get_formatted("total", doc) }}</td>
				</tr>

				<tr class="totals-row">
					<td colspan="5" class="text-right">Discount</td>
					<td class="text-right">{% if doc.discount_amount %}{{ doc.get_formatted("discount_amount", doc) }}{% endif %}</td>
				</tr>

				{%- for tax in doc.taxes -%}
				<tr class="totals-row">
					<td colspan="5" class="text-right">{{ tax.description }}</td>
					<td class="text-right text-bold">{{ tax.get_formatted("tax_amount", doc) }}</td>
				</tr>
				{%- endfor -%}

				<tr class="totals-row">
					<td colspan="5" class="text-right">NET AMOUNT</td>
					<td class="text-right text-bold">{{ doc.get_formatted("grand_total", doc) }}</td>
				</tr>

                <tr class="amount-words-row">
                    <td colspan="6" class="text-left">
                        Amount In Words: <strong>{{ doc.in_words }}</strong>
                    </td>
                </tr>
			</tbody>
		</table>

		<!-- Dynamic Signatures -->
		<table class="signature-section">
			<tr>
				<td>
					<strong>Declaration:</strong><br><br><br>
					_________________________<br>
					Customer's Seal and Signature
				</td>
				<td>
					<!-- Stamp Space -->
				</td>
				<td>
					<strong>For {{ doc.company }}</strong><br><br><br>
					_________________________<br>
					Authorised Signature
				</td>
			</tr>
		</table>

		<!-- Terms and Conditions Section -->
		{% if doc.terms %}
		<div class="terms-section">
			<strong>TERMS AND CONDITIONS:</strong><br>
			{{ doc.terms }}
		</div>
		{% endif %}

	</div>

    <div id="footer-html" class="visible-pdf">
        {% if not no_letterhead and footer %}
            <div class="letter-head-footer">
                {{ footer }}
            </div>
        {% endif %}
    </div>

</div>
{% endfor %}
